<?php require __DIR__."/../bootstrap.php";require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!empty($_POST['safe_browsing_api_key'])&&!secret_is_masked_input((string)$_POST['safe_browsing_api_key']))set_secret_setting('safe_browsing_api_key',trim((string)$_POST['safe_browsing_api_key']));flash('success','Threat intelligence settings saved.');redirect('/admin/security/');}$title="Security";require __DIR__.'/../includes/header.php';?><div class="page-head"><div><span class="eyebrow">SECURITY</span><h1>Security controls</h1><p>Abuse prevention, threat intelligence and application hardening.</p></div></div><div class="card"><h2>Protection layers</h2><ul><li>CSRF tokens on state-changing forms</li><li>PDO prepared statements</li><li>password_hash/password_verify</li><li>Session regeneration on login</li><li>Server-side admin authorization</li><li>Installation lock</li><li>Internal directory blocking through Apache</li><li>Secrets are encrypted at rest and never printed in frontend HTML</li><li>Redirect/API rate limiting with APCu when available and MySQL fallback</li><li>Bot/crawler exclusion from click metrics</li><li>Cloudflare country headers are consumed without storing raw visitor IPs</li></ul></div><section class="card"><h2>Google Safe Browsing</h2><p class="muted">Optional. When configured, new/updated destinations are checked before activation. If the provider is temporarily unavailable, the current policy is fail-open so link creation is not blocked by an outage.</p><form method="post"><?php echo csrf_field();?><label>API key<div class="secret-control" data-secret-scope="system" data-secret-key="safe_browsing_api_key"><input type="password" name="safe_browsing_api_key" value="<?=secret_setting('safe_browsing_api_key','')?'••••••••':''?>" data-secret-input data-masked="<?=secret_setting('safe_browsing_api_key','')?1:0?>" placeholder="Enter or replace key"><button type="button" class="secret-action" data-secret-eye>👁</button><button type="button" class="secret-action" data-secret-copy>Copy</button></div></label><button class="btn">Save security settings</button></form><p class="muted">Configured: <strong><?=secret_setting('safe_browsing_api_key','')?'Yes':'No'?></strong></p></section><?php require __DIR__.'/../includes/footer.php'; ?>
